module PluginTest

using Test
using KernelSmoothing
using KernelSmoothing: _fmin

# reference bandwidths from nprobust 1.0.0, generated by data/lpbw_golden.R
include(joinpath(@__DIR__, "data", "lpbw_golden.jl"))

const I = 1:400
const X = round.(mod.(I .* 0.6180339887498949, 1), digits = 2)
const Y = sin.(2π .* X) .+ 0.3 .* sin.(7.3 .* I)
const W = 1.0 .+ mod.(I, 3)
const EVAL = [0, 0.3, 0.5, 1]
const NPKERNELS = Dict("epa" => EpanechnikovKernel(), "tri" => TriangularKernel(), "uni" => UniformKernel())

@testset "agrees with nprobust" begin
  for c in LPBWSELECT
    vce = c.vce == "nn" ? NNVariance(3) : HCVariance(parse(Int, c.vce[3:end]))
    d = SmoothingData(X, Y; weights = c.weighted ? W : nothing)
    base = c.bwselect == "imse-dpi" ? IMSEOptimal(regularization = c.regul, interior = c.interior) :
           MSEOptimal(regularization = c.regul, interior = c.interior)
    rule = c.bwselect == "ce-rot" ? CoverageOptimal(base) : base
    s = selectbandwidth(rule, d, NPKERNELS[c.kernel]; degree = c.p, derivative = c.deriv, points = EVAL, vce,
                        compat = true)
    # R's optimize stops at an absolute tolerance, which the even cases inherit
    @test [s.h;] ≈ c.h rtol = 1e-7   # IMSEOptimal gives one bandwidth
    @test [s.details.b;] ≈ c.b rtol = 1e-7
  end
end

@testset "fits with plug-in bandwidths" begin
  d = SmoothingData(X, Y)
  # nprobust's default: MSE-optimal at one point, IMSE-optimal at several
  m1 = fit(LocalPolynomialRegression, d; points = [0.3], compat = true)
  @test m1.selection.rule == MSEOptimal()
  @test m1.h ≈ [LPBWSELECT[1].h[2]] rtol = 1e-10
  @test m1.b == m1.h   # rho = 1
  m = fit(LocalPolynomialRegression, d; points = EVAL, compat = true)
  @test m.selection.rule == IMSEOptimal()
  @test all(m.h .≈ LPBWSELECT[8].h[1])
  # the selected pilot bandwidths, if asked for
  ms = fit(LocalPolynomialRegression, d; bandwidth = MSEOptimal(), pilot = :selected, points = EVAL, compat = true)
  @test ms.b ≈ LPBWSELECT[1].b rtol = 1e-10
  @test_throws ArgumentError fit(LocalPolynomialRegression, d; bandwidth = 0.1, pilot = :selected)
  # averaged over the evaluation points instead of nprobust's grid
  s = selectbandwidth(IMSEOptimal(grid = :points), d, EpanechnikovKernel(); points = EVAL, compat = true)
  @test s.details.grid == EVAL && s.h != LPBWSELECT[8].h[1]
  @test_throws ArgumentError IMSEOptimal(grid = :all)
  @test_throws ArgumentError IMSEOptimal(grid = 0)
end

@testset "adaptive pilot bandwidths" begin
  # a sharp peak: nprobust's pilots end at the cap at interior points, so that its
  # bandwidths are about twice the optimal ones there, while the adaptive pilots
  # adapt through cross-validation
  n = 5000
  xs = [mod(0.7548776662466927i, 1.0) for i in 1:n]
  m(x) = exp(-32 * (x - 0.5)^2) + 0.5x
  ys = m.(xs) .+ 0.3 .* sin.(1.0e4 .* (1:n))   # deterministic noise with variance 0.045
  d = SmoothingData(xs, ys)
  k = EpanechnikovKernel()
  hstar = (0.045 * 0.6 / (4n * 0.01 * 64^2))^(1 / 5)   # the optimal bandwidth at 0.5
  s = selectbandwidth(MSEOptimal(), d, k; points = [0.5])
  sc = selectbandwidth(MSEOptimal(), d, k; points = [0.5], compat = true)
  @test abs(s.h[1] / hstar - 1) < 0.25
  @test sc.h[1] / hstar > 1.5
  @test sc.details.b[1] == max(0.5 - minimum(xs), maximum(xs) - 0.5)   # the cap: the farther end of the data
  hcv = selectbandwidth(CrossValidation(), d, k).h
  @test s.details.crossvalidation == hcv
  ρ = selectbandwidth(RuleOfThumb(), d, k; degree = 2, derivative = 2).h / selectbandwidth(RuleOfThumb(), d, k).h
  @test s.details.b[1] ≈ hcv * ρ
  # the integrated rule uses the same pilot for all points
  si = selectbandwidth(IMSEOptimal(), d, k)
  @test si.details.b ≈ hcv * ρ && si.details.crossvalidation == hcv
  @test fit(LocalPolynomialRegression, d; points = [0.25, 0.5]).h ≈ fill(si.h, 2)
  # even p - ν: the bias needs the derivative of order p + 2, with its own pilot
  s0 = selectbandwidth(MSEOptimal(), d, k; degree = 0, points = [0.3, 0.5])
  @test all(isfinite, s0.h) && all(s0.h .> 0)
  @test selectbandwidth(MSEOptimal(), d, k; degree = 2, derivative = 1, points = [0.3]).h[1] > 0
end

@testset "even p - ν and the integrated rule" begin
  n = 2000
  xs = [mod(0.7548776662466927i, 1.0) for i in 1:n]
  ys = sin.(2π .* xs) .+ 0.5 .* xs .+ 0.3 .* sin.(1.0e4 .* (1:n))
  k = EpanechnikovKernel()
  # nprobust's squared bias for even p - ν adds the regularization term, which has the
  # units of B₁², to B₁; the adaptive rule's bandwidth does not depend on the units of y
  for (deg, ν) in ((0, 0), (2, 1))
    h = [selectbandwidth(MSEOptimal(), SmoothingData(xs, s .* ys), k; degree = deg, derivative = ν,
                         points = [0.0, 0.5]).h for s in (1.0, 10.0, 0.1)]
    @test h[2] ≈ h[1] rtol = 1e-8
    @test h[3] ≈ h[1] rtol = 1e-8
  end
  hi = [bandwidth(IMSEOptimal(), SmoothingData(xs, s .* ys), k; degree = 0) for s in (1.0, 0.1)]
  @test hi[2] ≈ hi[1] rtol = 1e-8
  # without regularization, nprobust's form finds the zero of the squared bias
  h0 = selectbandwidth(MSEOptimal(regularization = 0), SmoothingData(xs, ys), k; degree = 0, points = [0.0]).h[1]
  @test h0 < 0.2
  # the integrated rule keeps the regularization of MSEOptimal and the cap at the range
  xl = collect(range(0, 1; length = 500))
  yl = 2 .* xl .+ 1 .+ 0.1 .* sin.(1.0e4 .* (1:500))
  hr = [bandwidth(IMSEOptimal(regularization = r), SmoothingData(xl, yl), k) for r in (0, 1, 10)]
  @test hr[1] >= hr[2] > hr[3] && all(hr .<= 1)
  @test bandwidth(IMSEOptimal(), SmoothingData(xl, 2 .* xl .+ 1), k) <= 1   # nprobust's rule gives 966
  @test bandwidth(IMSEOptimal(), SmoothingData(xl, 2 .* xl .+ 1), k; compat = true) > 1
end

@testset "coverage-error-optimal bandwidths" begin
  d = SmoothingData(X, Y)
  n = 400
  mse = selectbandwidth(MSEOptimal(), d, EpanechnikovKernel(); points = EVAL)
  ce = selectbandwidth(CoverageOptimal(), d, EpanechnikovKernel(); points = EVAL)
  @test ce.h ≈ mse.h .* n^(-1 / 20)                 # p = 1: n^(-p/((2p+3)(p+3)))
  @test ce.details.mse == mse.h
  # the interior convention leaves local linear bandwidths unchanged
  ci = selectbandwidth(CoverageOptimal(convention = :interior), d, EpanechnikovKernel(); points = EVAL)
  @test ci.h ≈ mse.h
  @test ci.details.b ≈ ce.details.b
  c3 = selectbandwidth(CoverageOptimal(convention = :interior), d, EpanechnikovKernel(); degree = 3, points = [0.5])
  m3 = selectbandwidth(MSEOptimal(), d, EpanechnikovKernel(); degree = 3, points = [0.5])
  @test c3.h ≈ m3.h .* n^(-2 / (9 * 7))           # p = 3: n^(-(p-1)/((2p+3)(p+4)))
  @test_throws ArgumentError CoverageOptimal(convention = :boundary)
end

@testset "location and scale" begin
  # For odd p - ν the bandwidths are equivariant; the even cases minimize numerically
  # with R's absolute tolerance, which is not. Data without ties, since with ties an
  # observation can sit exactly at the edge of a window, where rounding after the
  # change of scale moves it in or out.
  xs = [mod(0.7548776662466927i, 1.0) for i in 1:400]
  d = SmoothingData(xs, Y)
  d2 = SmoothingData(3 .+ 2 .* xs, Y)
  for (p, ν) in ((1, 0), (2, 1))
    s = selectbandwidth(MSEOptimal(), d, EpanechnikovKernel(); degree = p, derivative = ν, points = [0.3, 0.7])
    s2 = selectbandwidth(MSEOptimal(), d2, EpanechnikovKernel(); degree = p, derivative = ν, points = [3.6, 4.4])
    @test s2.h ≈ 2 .* s.h rtol = 1e-9
    @test s2.details.b ≈ 2 .* s.details.b rtol = 1e-9
  end
end

@testset "other kernels" begin
  # kernels outside nprobust get the exact normal-reference constant for the variances
  d = SmoothingData(X, Y)
  s = selectbandwidth(MSEOptimal(), d, BiweightKernel(); points = [0.3, 0.6])
  @test all(isfinite, s.h) && all(s.h .> 0)
  @test KernelSmoothing._nrconstant(BiweightKernel()) ≈ (8 * sqrt(π) * (5 / 7) / (3 / 49))^(1 / 5)
  @test KernelSmoothing._nrconstant(GaussianKernel()) == 1.06
end

@testset "Brent's method" begin
  @test _fmin(x -> (x - 0.3)^2 + 1, 0.0, 1.0) ≈ 0.3 atol = 1e-4
  @test _fmin(x -> abs(x - 2.5), 0.0, 10.0) ≈ 2.5 atol = 1e-4
  @test _fmin(x -> -x, 0.0, 1.0) ≈ 1.0 atol = 1e-3   # at an end
  # a NaN end used to make the search run forever
  @test_throws ArgumentError _fmin(x -> x^2, 0.0, NaN)
  @test_throws ArgumentError _fmin(x -> x^2, 1.0, 1.0)
  @test_throws ArgumentError IMSEOptimal(grid = 1)
end

@testset "fits that are not identified" begin
  # local constant fits use the second bias term; local linear ones do not, so that
  # its fit of order p + 2 cannot fail for them
  xd = repeat(collect(range(1.0, 2.0; length = 6)), inner = 50)
  yd = log.(xd) .+ 0.2 .* sin.(7.3 .* (1:300))
  @test all(isfinite, bandwidth(MSEOptimal(), SmoothingData(xd, yd), EpanechnikovKernel(); points = [1.5]))
  @test_throws ArgumentError selectbandwidth(MSEOptimal(), SmoothingData(fill(1.0, 30), rand(30)), EpanechnikovKernel())
  @test_throws ArgumentError selectbandwidth(IMSEOptimal(), SmoothingData(fill(1.0, 30), rand(30)), EpanechnikovKernel())
end

# a user kernel, without moments of its square
struct CosineKernel <: AbstractKernel end
(::CosineKernel)(u::Real) = abs(u) <= 1 ? π / 4 * cos(π * u / 2) : 0.0
KernelSmoothing.support(::CosineKernel) = (-1.0, 1.0)
KernelSmoothing.moment(::CosineKernel, j::Integer) =
  isodd(j) ? 0.0 : j == 0 ? 1.0 : j == 2 ? 1 - 8 / π^2 : j == 4 ? 1 - 48 / π^2 + 384 / π^4 :
  1 - 120 / π^2 + 5760 / π^4 - 46080 / π^6   # j = 6

@testset "the default rules where a fit exists" begin
  # four distinct values: the stages of the plug-in rule widen windows with too few
  x = repeat([1.0, 4 / 3, 5 / 3, 2.0], inner = 75)
  y = log.(x) .+ 0.2 .* sin.(7.3 .* (1:300))
  m = fit(LocalPolynomialRegression, x, y; points = [1.0, 1.5])
  # (at 1.0 the window of this bandwidth holds one distinct value, so the estimate
  # there is NaN, while the floor counts observations)
  @test all(isfinite, m.h) && isfinite(m.estimate[2])
  @test all(isfinite, fit(LocalPolynomialRegression, x, y; points = [1.5]).h)
  # heaped data without the floor: the interquartile range vanishes
  xq = [fill(0.5, 200); [mod(0.618034i, 1) for i in 1:100]]
  yq = sin.(3 .* xq) .+ 0.1 .* cos.(17 .* (1:300))
  @test all(isfinite, fit(LocalPolynomialRegression, xq, yq; points = [0.3, 0.5], minobs = 0).h)
  # constant responses leave nothing to minimize, which the error says
  xc = [mod(0.7548776662466927i, 1.0) for i in 1:300]
  @test_throws "the responses are constant" fit(LocalPolynomialRegression, xc, fill(2.0, 300))
  @test_throws "the responses are constant" fit(LocalPolynomialRegression, xc, fill(2.0, 300); points = [0.5])
  # cross-validation on three observations reaches beyond its floor
  @test isfinite(bandwidth(CrossValidation(), SmoothingData([0.0, 1.0, 2.0], [0.0, 1.0, 0.0]), EpanechnikovKernel()))
  # the plug-in rules with a user kernel, whose square has its moments by quadrature
  xs = [sin(1.618i) + 0.3cos(2.7i) for i in 1:500]
  k = CosineKernel()
  @test all(isfinite, fit(PointwiseDensity, xs; kernel = k, points = [0.0]).h)
  @test all(isfinite, fit(LocalPolynomialRegression, xs, sin.(xs); kernel = k, points = [0.0]).h)
  @test isfinite(bandwidth(RuleOfThumb(), SmoothingData(xs, sin.(xs)), k))
end

end
